# >>> generated by scripts/06_demokin_scripts.R, start
# Runs the 32 DemoKin scripts of this folder and collects their results.
# Run it from this folder (setwd to demokin/), or source it from RStudio.

dir <- tryCatch(dirname(rstudioapi::getActiveDocumentContext()$path), error = function(e) "")
if (!nzchar(dir)) dir <- getwd()
files <- setdiff(list.files(dir, pattern = "\\.R$", full.names = TRUE),
                 file.path(dir, "run_all.R"))
res <- do.call(rbind, lapply(files, function(f) source(f, local = new.env())$value))
utils::write.csv(res, file.path(dir, "demokin_results.csv"), row.names = FALSE)
print(res, digits = 3)
# <<< end
